/bin/bash -lc "python - <<'PY'
from openpyxl import load_workbook
from pathlib import Path
from collections import Counter
base=Path('inputs')
# carriers
wb=load_workbook(base/'230215_Trio_Status.xlsx',read_only=True,data_only=True);ws=wb.active;ws.reset_dimensions();it=ws.iter_rows(values_only=True);h=[str(x).strip() if x is not None else None for x in next(it)];carriers=set()
for row in it:
 d=dict(zip(h,row));
 if str(d.get('BLM Mutation Status')).strip()=='Carrier': carriers.add(str(d.get('Sample ID')).strip())
# genes
wb=load_workbook(base/'230214_Schenz_et_al_2022_CHIP_Genes.xlsx',read_only=True,data_only=True);ws=wb.active;ws.reset_dimensions();genes={str(row[0]).strip().upper() for row in ws.iter_rows(values_only=True) if row and row[0]}

def sid_for(p):
 s=p.stem.split('_CHIP_',1)[1]
 return s.split('-',1)[0] if s[0].isdigit() else s
def n(v):
 try:return float(v)
 except:return None
def has_chip(d):
 # exact gene tokens, considering comma-separated gene names, case-insensitive
 toks={x.strip().upper() for x in str(d.get('Gene Names') or '').split(',')}
 return bool(toks & genes)
def bad(d):
 s=str(d.get('Sequence Ontology (Combined)') or '').lower()
 return any(x in s for x in ('intron','intergenic','utr')) or str(d.get('Zygosity')).strip().lower()=='reference'
rows=[]
for p in (base/'CHIP_DP10_GQ20_PASS').glob('*.xlsx'):
 sid=sid_for(p)
 if sid not in carriers:continue
 wb=load_workbook(p,read_only=True,data_only=True);ws=wb.active;ws.reset_dimensions();it=ws.iter_rows(values_only=True);next(it);hh=[x.strip() if isinstance(x,str) else x for x in next(it)]
 for row in it:
  d=dict(zip(hh,row));d['Sample']=sid
  if has_chip(d) and n(d.get('Variant Allele Freq')) is not None and n(d['Variant Allele Freq'])<.3 and not bad(d): rows.append(d)
print('gene-intersect filtered',len(rows),'classification',Counter(r.get('Classification') for r in rows))
cls=[r for r in rows if r.get('Classification') is not None and str(r.get('Classification')).strip() not in ('','None')]
print('classified',len(cls),'num',sum(str(r.get('Classification')).strip() in {'Benign','Likely Benign'} for r in cls))
for r in rows:
 if str(r.get('Classification')).strip() not in {'Benign','Likely Benign','None'}:print('other',r)
PY"
